using System.Security.Cryptography;
using System.Text.RegularExpressions;
namespace Aurora.Core;
public static class VehicleSoundFiles
{
 public sealed record Layer(string Reference,bool Workshop=false);
 public static Layer[] Layers(string script){var tokens=VehicleScript.Tokens(script);return VehicleScript.Fields(script).Where(f=>f.Key is "SOUND_PARAMS" or "SOUND_PARAMS_WORKSHOP").Select(f=>new Layer(tokens.FirstOrDefault(t=>t.Key==f.Key&&t.Occurrence==f.Occurrence&&t.Index==0)?.Value??throw new InvalidDataException("Empty sound layer"),f.Key=="SOUND_PARAMS_WORKSHOP")).ToArray();}
 public static string SetLayers(string script,IEnumerable<Layer> layers){var values=layers.ToArray();if(values.Any(v=>string.IsNullOrWhiteSpace(v.Reference)||v.Reference.IndexOfAny(['\r','\n','"'])>=0))throw new InvalidDataException("Invalid sound reference");if(Layers(script).SequenceEqual(values))return script;foreach(var f in VehicleScript.Fields(script).Where(f=>f.Key is "SOUND_PARAMS" or "SOUND_PARAMS_WORKSHOP").Reverse())script=VehicleScript.RemoveEntry(script,f.Key,f.Occurrence);int native=0,workshop=0;foreach(var layer in values)script=VehicleScript.SetArguments(script,layer.Workshop?"SOUND_PARAMS_WORKSHOP":"SOUND_PARAMS",layer.Workshop?workshop++:native++,[layer.Reference]);return script;}
 public static HashSet<string> Registry(string media){string file=Path.Combine(media,"sounds","script.ini");if(!File.Exists(file))throw new FileNotFoundException("Sound registry not found",file);return Regex.Matches(File.ReadAllText(file),@"(?m)^[\t ]*\$EVENT(?:3D|2D)?[\t ]+(\S+)").Select(m=>m.Groups[1].Value).ToHashSet(StringComparer.Ordinal);}
 public static string[] MissingEvents(string text,IReadOnlySet<string> registry)=>Regex.Matches(text,@"(?m)^[\t ]*\$TEXT[\t ]+\w+[\t ]+(\S+)").Select(m=>m.Groups[1].Value).Where(v=>!registry.Contains(v)).Distinct().ToArray();
 public static string[] Overlaps(IEnumerable<string> layers)=>layers.SelectMany((text,i)=>Regex.Matches(text,@"(?m)^[\t ]*\$(?:TEXT|FLOAT)[\t ]+(\w+)").Select(m=>(Name:m.Groups[1].Value,Index:i))).GroupBy(v=>v.Name).Where(g=>g.Select(v=>v.Index).Distinct().Count()>1).Select(g=>g.Key).ToArray();
 public static string Validate(string path){string text=File.ReadAllText(path);if(text.Length>2*1024*1024||!Regex.IsMatch(text,@"(?m)^\s*\$(TEXT|FLOAT)\s+\w+\s+[^\r\n]+"))throw new InvalidDataException("Invalid vehicle sound INI");return text;}
 public static string Map(string script,Func<string,string> map)=>VehicleScript.RewriteTokens(script,t=>t.Key=="SOUND_PARAMS_WORKSHOP"&&t.Index==0?map(t.Value):null);
 public static string Resolve(string reference,string folder){string path=Path.IsPathRooted(reference)?reference:Path.Combine(folder,reference.Replace('/',Path.DirectorySeparatorChar));if(!File.Exists(path))throw new FileNotFoundException("Sound INI not found",path);return path;}
 public static string Export(string script,string folder,string destination)=>Map(script,reference=>{string path=Resolve(reference,folder);string text=Validate(path);string name="sound-"+Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)))[..16].ToLowerInvariant()+".ini";File.WriteAllText(Path.Combine(destination,name),text);return name;});
}
